              >
                إغلاق النافذة
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Footer */}
      <footer className="mt-8 border-t border-slate-200 bg-white py-6 no-print">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center text-xs text-slate-500 space-y-2">
          <p className="font-bold text-slate-800 text-sm">
            مشروع "نبض الأمان" — المساعد الطبي الذكي لارتفاع ضغط الدم (Hypertension AI Assistant)
          </p>
          <p className="max-w-2xl mx-auto leading-relaxed">
            تم التطوير باستخدام Next.js (App Router) و TypeScript و Tailwind CSS و Lucide Icons لدعم مسابقات الابتكار والتحكيم الطبي والأكاديمي، مع الالتزام الصارم بإرشادات منظمة الصحة العالمية (WHO) وجمعية القلب الأمريكية (AHA) والجمعية الأوروبية لأمراض القلب (ESC) والمعهد الوطني للصحة (NIH) ومايو كلينك (Mayo Clinic) ووزارة الصحة العراقية.
          </p>
        </div>
      </footer>
    </div>
  );
}

@import "tailwindcss";

@layer base {
  :root {
    --font-cairo: 'Cairo', 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  }

  * {
    box-sizing: border-box;
  }

  body {
    font-family: var(--font-cairo);
    background-color: #f8fafc;
    color: #0f172a;
    direction: rtl;
    text-align: right;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: #f1f5f9;
}
::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: #94a3b8;
}

/* Emergency Alert Pulsing Glow */
@keyframes emergencyPulse {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(220, 38, 38, 0.4);
    border-color: #dc2626;
  }
  50% {
    box-shadow: 0 0 0 10px rgba(220, 38, 38, 0);
    border-color: #ef4444;
  }
}

.emergency-pulse-active {
  animation: emergencyPulse 1.8s infinite;
}

/* Heartbeat pulse animation */
@keyframes heartbeat {
  0% { transform: scale(1); }
  14% { transform: scale(1.15); }
  28% { transform: scale(1); }
  42% { transform: scale(1.15); }
  70% { transform: scale(1); }
}

.animate-heartbeat {
  animation: heartbeat 1.5s ease-in-out infinite;
}

/* Medical Typography & Markdown Styling */
.prose-medical {
  font-size: 0.925rem;
  line-height: 1.75;
  color: #1e293b;
}

.prose-medical h1 {
